const defaults = { color: "blue", size: "medium", weight: 10 }
const userConfig = { color: null, size: "large", weight: 0 }
return {
  color: userConfig.color ?? defaults.color,
  size: userConfig.size ?? defaults.size,
  weight: userConfig.weight ?? defaults.weight
}
